import type { BankQuestion } from "@/lib/bank";

/** Trigonometry (Mathematics (JEE)): 177 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"math-trigonometry-1","question":"The value of sin 150° is:","options":["−1/2","√3/2","1/2","−√3/2"],"answer":2,"explanation":"sin 150° = sin(180° − 30°) = sin 30° = 1/2. Sine is positive in the second quadrant; cos 150° = −√3/2 is the distractor.","difficulty":"easy","source":"JEE Main"},
  {"id":"math-trigonometry-2","question":"The principal value of sin⁻¹(−1/2) is:","options":["7π/6","−π/6","5π/6","π/6"],"answer":1,"explanation":"The principal range of sin⁻¹ is [−π/2, π/2]; the angle in this range with sine −1/2 is −π/6. 7π/6 and 5π/6 lie outside the range (and sin 5π/6 = +1/2).","difficulty":"easy","source":"JEE Main"},
  {"id":"math-trigonometry-3","question":"In a triangle ABC with circumradius R, a/sin A equals:","options":["R","R/2","2R","r"],"answer":2,"explanation":"Sine rule: a/sin A = b/sin B = c/sin C = 2R, where R is the circumradius (not the inradius r).","difficulty":"easy","source":"JEE Main"},
  {"id":"math-trigonometry-4","question":"The general solution of tan x = √3 is:","options":["x = 2nπ + π/3","x = nπ ± π/3","x = nπ + π/6","x = nπ + π/3"],"answer":3,"explanation":"tan has period π and tan(π/3) = √3, so x = nπ + π/3, n an integer. The form nπ ± π/3 belongs to tan²x = 3, and 2nπ + π/3 misses half the solutions.","difficulty":"moderate","source":"JEE Main"},
  {"id":"math-trigonometry-5","question":"The value of sin 15° is:","options":["(√3 + 1)/(2√2)","(√3 − 1)/2","(√3 − 1)/(2√2)","(√2 − 1)/2"],"answer":2,"explanation":"sin 15° = sin(45° − 30°) = sin 45° cos 30° − cos 45° sin 30° = (1/√2)(√3/2) − (1/√2)(1/2) = (√3 − 1)/(2√2) ≈ 0.259. (√3 + 1)/(2√2) is cos 15°.","difficulty":"moderate","source":"JEE Main"},
  {"id":"math-trigonometry-6","question":"tan⁻¹(1/2) + tan⁻¹(1/3) equals:","options":["π/3","π/4","π/6","π/2"],"answer":1,"explanation":"Since (1/2)(1/3) < 1, tan⁻¹x + tan⁻¹y = tan⁻¹[(x + y)/(1 − xy)] = tan⁻¹[(5/6)/(5/6)] = tan⁻¹1 = π/4.","difficulty":"moderate","source":"JEE Main"},
  {"id":"math-trigonometry-7","question":"From a point on the ground 30 m from the foot of a tower, the angle of elevation of its top is 60°. The height of the tower is:","options":["30√3 m","30/√3 m","30 m","60 m"],"answer":0,"explanation":"tan 60° = h/30, so h = 30 tan 60° = 30√3 m ≈ 52 m. Using 30/tan 60° = 30/√3 (the distractor) would be the answer if 30 m were the height.","difficulty":"moderate","source":"JEE Main"},
  {"id":"math-trigonometry-8","question":"In a triangle ABC, a = 7, b = 8 and c = 5. The angle A is:","options":["30°","45°","120°","60°"],"answer":3,"explanation":"Cosine rule: cos A = (b² + c² − a²)/(2bc) = (64 + 25 − 49)/(2 × 8 × 5) = 40/80 = 1/2, so A = 60°.","difficulty":"moderate","source":"JEE Main"},
  {"id":"math-trigonometry-9","question":"If sin θ + cos θ = √2 and 0 < θ < π/2, then θ equals:","options":["π/4","π/6","π/3","π/2"],"answer":0,"explanation":"sin θ + cos θ = √2 sin(θ + π/4). This equals √2 only when sin(θ + π/4) = 1, i.e. θ + π/4 = π/2, so θ = π/4. (Also √2 is the maximum of sin θ + cos θ, attained only there.)","difficulty":"moderate","source":"JEE Main"},
  {"id":"math-trigonometry-10","question":"The value of cos 20° cos 40° cos 80° is:","options":["1/4","1/8","1/2","√3/8"],"answer":1,"explanation":"Use cos θ cos(60° − θ) cos(60° + θ) = (cos 3θ)/4 with θ = 20°: cos 20° cos 40° cos 80° = cos 60°/4 = (1/2)/4 = 1/8.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-trigonometry-11","question":"The number of solutions of 2sin²x − 3sin x + 1 = 0 in [0, 2π] is:","options":["2","4","3","1"],"answer":2,"explanation":"(2sin x − 1)(sin x − 1) = 0 gives sin x = 1/2 (x = π/6, 5π/6) or sin x = 1 (x = π/2 only). Total 3 solutions.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-trigonometry-12","question":"sin⁻¹(4/5) + sin⁻¹(5/13) = sin⁻¹(x). Then x equals:","options":["56/65","63/65","33/65","16/65"],"answer":1,"explanation":"Let A = sin⁻¹(4/5), B = sin⁻¹(5/13); cos A = 3/5, cos B = 12/13. sin(A + B) = sin A cos B + cos A sin B = 48/65 + 15/65 = 63/65. Since both angles are acute and cos(A + B) = 36/65 − 20/65 > 0, A + B is acute, so x = 63/65.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-trigonometry-13","question":"The inradius of the triangle with sides 13, 14 and 15 is:","options":["65/8","6","84","4"],"answer":3,"explanation":"s = 21, Δ = √(21 × 8 × 7 × 6) = √7056 = 84. Inradius r = Δ/s = 84/21 = 4. The circumradius R = abc/(4Δ) = 2730/336 = 65/8 is the distractor.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-trigonometry-14","question":"From the top of a 60 m high cliff, the angles of depression of two boats on the same side of the cliff are 30° and 60°. The distance between the boats is:","options":["20√3 m","40√3 m","60√3 m","40 m"],"answer":1,"explanation":"Distances from the foot of the cliff are 60/tan 30° = 60√3 m and 60/tan 60° = 60/√3 = 20√3 m. Difference = 60√3 − 20√3 = 40√3 m ≈ 69.3 m.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-trigonometry-15","question":"If A + B = 45°, then (1 + tan A)(1 + tan B) equals:","options":["1","√2","4","2"],"answer":3,"explanation":"tan(A + B) = 1 gives tan A + tan B = 1 − tan A tan B. Then (1 + tan A)(1 + tan B) = 1 + (tan A + tan B) + tan A tan B = 1 + 1 = 2.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-trigonometry-16","question":"The minimum value of sin²x + cos⁴x for real x is:","options":["3/4","1/2","1","0"],"answer":0,"explanation":"Let t = cos²x ∈ [0, 1]. Then sin²x + cos⁴x = 1 − t + t² = (t − 1/2)² + 3/4, which is least at t = 1/2 with value 3/4 (and the maximum, at t = 0 or 1, is 1).","difficulty":"hard","source":"JEE Main"},
  {"id":"math-trigonometry-17","question":"If sin⁻¹x + sin⁻¹y + sin⁻¹z = 3π/2, then x + y + z equals:","options":["0","3","1","−3"],"answer":1,"explanation":"Each sin⁻¹ term is at most π/2, so the sum can reach 3π/2 only when each equals π/2, forcing x = y = z = 1. Hence x + y + z = 3.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-trigonometry-18","question":"The number of solutions of sin x + cos x = 1 in the closed interval [0, 2π] is:","options":["2","4","1","3"],"answer":3,"explanation":"√2 sin(x + π/4) = 1 gives sin(x + π/4) = 1/√2, so x + π/4 = π/4, 3π/4 or 9π/4 (as x + π/4 ranges over [π/4, 9π/4]). Thus x = 0, π/2, 2π: three solutions, because both end points 0 and 2π are included.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-trigonometry-19","question":"Consider the following statements:\n(I) tan θ + cot θ = 2 cosec 2θ.\n(II) cos 36° − cos 72° = 1/2.\n(III) sin 10° sin 50° sin 70° = 1/8.\n(IV) cot 15° − tan 15° = 2√3.\nHow many of these statements are correct?","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"(I) tan θ + cot θ = 1/(sin θ cos θ) = 2/sin 2θ. (II) cos 36° = (√5 + 1)/4 and cos 72° = (√5 − 1)/4, difference 1/2. (III) sin θ sin(60° − θ) sin(60° + θ) = (sin 3θ)/4 = sin 30°/4 = 1/8. (IV) cot 15° − tan 15° = (cos²15° − sin²15°)/(sin 15° cos 15°) = 2cos 30°/sin 30° = 2√3. All four are correct.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"math-trigonometry-20","question":"In a triangle ABC, if a cos A = b cos B, then the triangle is necessarily:","options":["isosceles only","right-angled only","isosceles or right-angled","equilateral"],"answer":2,"explanation":"By the sine rule, sin A cos A = sin B cos B, i.e. sin 2A = sin 2B. So either 2A = 2B (A = B, isosceles) or 2A = π − 2B (A + B = π/2, so C = π/2, right-angled). Choosing only one case loses the other.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-trigonometry-21","question":"If cos(A − B) = 3/5 and tan A tan B = 2, then cos(A + B) equals:","options":["−1/5","1/5","−3/5","1/15"],"answer":0,"explanation":"cos(A + B)/cos(A − B) = (cos A cos B − sin A sin B)/(cos A cos B + sin A sin B) = (1 − tan A tan B)/(1 + tan A tan B) = (1 − 2)/(1 + 2) = −1/3. Hence cos(A + B) = (−1/3)(3/5) = −1/5.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"math-trigonometry-22","question":"The number of solutions of tan x + sec x = 2 cos x in [0, 2π] is:","options":["3","1","4","2"],"answer":3,"explanation":"With cos x ≠ 0: (sin x + 1)/cos x = 2 cos x → 1 + sin x = 2(1 − sin²x) → 2sin²x + sin x − 1 = 0 → sin x = 1/2 or sin x = −1. sin x = −1 makes cos x = 0 and is rejected. sin x = 1/2 gives x = π/6, 5π/6: two solutions.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"math-trigonometry-24","question":"The angle of elevation of the top of a vertical tower from a point A due south of it is 30°, and from a point B due east of it is 45°. If AB = 100 m, the height of the tower is:","options":["50√2 m","100/√3 m","50 m","25 m"],"answer":2,"explanation":"Let the height be h and the foot O. OA = h cot 30° = h√3 and OB = h cot 45° = h. Since OA ⊥ OB, AB² = OA² + OB² = 3h² + h² = 4h² = 10000, so h = 50 m.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-trigonometry-25","question":"The value of cos(π/7) cos(2π/7) cos(4π/7) is:","options":["1/8","−1/8","1/4","−1/4"],"answer":1,"explanation":"Multiply by 2³ sin(π/7) and use 2 sin θ cos θ = sin 2θ repeatedly: 8 sin(π/7) cos(π/7) cos(2π/7) cos(4π/7) = sin(8π/7) = −sin(π/7). Dividing by 8 sin(π/7) gives −1/8.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-trigonometry-26","question":"The sum to infinity Σ tan⁻¹[1/(k² + k + 1)] for k = 1, 2, 3, … equals:","options":["π/2","π/3","π/4","π/6"],"answer":2,"explanation":"1/(k² + k + 1) = [(k + 1) − k]/[1 + k(k + 1)], so each term is tan⁻¹(k + 1) − tan⁻¹k. The series telescopes to lim tan⁻¹(n + 1) − tan⁻¹1 = π/2 − π/4 = π/4.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-trigonometry-27","question":"In a triangle ABC, if (a + b + c)(b + c − a) = 3bc, then angle A equals:","options":["30°","90°","120°","60°"],"answer":3,"explanation":"(b + c)² − a² = 3bc gives b² + c² − a² = bc, so cos A = (b² + c² − a²)/(2bc) = 1/2 and A = 60°.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"math-trigonometry-28","question":"Consider the following statements (principal values throughout):\n(I) sin⁻¹(sin 5) = 5 − 2π.\n(II) cos⁻¹(cos(−π/3)) = −π/3.\n(III) tan⁻¹x + cot⁻¹x = π/2 for every real x.\n(IV) sec⁻¹2 = π/3.\nHow many of these statements are correct?","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"(I) true: 5 − 2π ≈ −1.28 lies in [−π/2, π/2] and has the same sine as 5. (II) false: cos⁻¹ returns values in [0, π], so cos⁻¹(cos(−π/3)) = π/3. (III) true, a standard identity. (IV) true: sec(π/3) = 2 and π/3 is in the principal range. Three are correct.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"math-trigonometry-29","question":"The number of solutions of sin⁴x + cos⁴x = sin x cos x in [0, 2π] is:","options":["4","2","1","0"],"answer":1,"explanation":"sin⁴x + cos⁴x = 1 − 2sin²x cos²x = 1 − (1/2)sin²2x and sin x cos x = (1/2)sin 2x. With t = sin 2x: 1 − t²/2 = t/2 → t² + t − 2 = 0 → t = 1 (t = −2 is impossible). sin 2x = 1 gives 2x = π/2, 5π/2, so x = π/4, 5π/4: two solutions.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-trigonometry-30","question":"In a triangle ABC, if a², b², c² are in AP, then cot A, cot B, cot C are in:","options":["GP","HP","AP","no particular progression"],"answer":2,"explanation":"cot A = (b² + c² − a²)/(4Δ) etc. So cot A + cot C = (2b²)/(4Δ), while 2cot B = 2(a² + c² − b²)/(4Δ) = 2(2b² − b²)/(4Δ) = 2b²/(4Δ) using a² + c² = 2b². Hence cot A + cot C = 2cot B: AP.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id": "math-trigonometry-31", "question": "The value of tan 15° is:", "options": ["2 − √3", "2 + √3", "√3 − 1", "(√3 − 1)/2"], "answer": 0, "explanation": "tan(45° − 30°) = (1 − 1/√3)/(1 + 1/√3) = (√3 − 1)/(√3 + 1) = (√3 − 1)²/2 = 2 − √3. 2 + √3 is tan 75°.", "difficulty": "easy", "source": "JEE Main pattern"},
  {"id": "math-trigonometry-32", "question": "The maximum value of 3 sin x + 4 cos x + 5 is:", "options": ["12", "5", "7", "10"], "answer": 3, "explanation": "a sin x + b cos x ranges over [−√(a² + b²), √(a² + b²)] = [−5, 5], so the maximum is 5 + 5 = 10.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "math-trigonometry-33", "question": "The fundamental period of f(x) = |sin x| + |cos x| is:", "options": ["π", "2π", "π/2", "π/4"], "answer": 2, "explanation": "f(x + π/2) = |cos x| + |sin x| = f(x), and no smaller positive number works (for example f(0) = 1 but f(π/4) = √2). So the period is π/2.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "math-trigonometry-34", "question": "In a triangle ABC, a = 3, b = 4 and C = 60°. Then c equals:", "options": ["√13", "5", "√37", "√7"], "answer": 0, "explanation": "c² = a² + b² − 2ab cos C = 9 + 16 − 12 = 13, so c = √13. 5 would need C = 90°.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "math-trigonometry-35", "question": "The value of cos²(π/8) + cos²(3π/8) + cos²(5π/8) + cos²(7π/8) is:", "options": ["1", "4", "0", "2"], "answer": 3, "explanation": "cos(3π/8) = sin(π/8), cos(5π/8) = −sin(π/8) and cos(7π/8) = −cos(π/8). The sum is 2(cos²(π/8) + sin²(π/8)) = 2.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-trigonometry-36", "question": "The number of solutions of cos x + cos 3x = cos 2x in [0, π] is:", "options": ["2", "3", "4", "5"], "answer": 1, "explanation": "cos x + cos 3x = 2cos 2x cos x, so cos 2x(2cos x − 1) = 0. cos 2x = 0 gives x = π/4, 3π/4; cos x = 1/2 gives x = π/3. That is 3 solutions.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-trigonometry-37", "question": "The value of tan 9° − tan 27° − tan 63° + tan 81° is:", "options": ["2", "4", "0", "8"], "answer": 1, "explanation": "tan 9° + tan 81° = tan 9° + cot 9° = 2/sin 18°, and tan 27° + tan 63° = 2/sin 54°. Difference = 2(1/sin 18° − 1/cos 36°) = 2[4/(√5 − 1) − 4/(√5 + 1)] = 2 × 4 × 2/4 = 4.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-trigonometry-38", "question": "The circumradius of the triangle with sides 5, 6 and 7 is:", "options": ["35/24", "6√6", "7√6/12", "35√6/24"], "answer": 3, "explanation": "s = 9 and the area is √(9·4·3·2) = 6√6. R = abc/(4Δ) = 210/(24√6) = 35/(4√6) = 35√6/24. 6√6 is the area.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-trigonometry-39", "question": "If tan θ = 3 tan φ with 0 < φ ≤ θ < π/2, the greatest possible value of θ − φ is:", "options": ["π/6", "π/3", "π/4", "π/12"], "answer": 0, "explanation": "tan(θ − φ) = 2t/(1 + 3t²) with t = tan φ > 0. By AM–GM, 1 + 3t² ≥ 2√3 t, so tan(θ − φ) ≤ 1/√3, with equality at t = 1/√3. The maximum of θ − φ is π/6.", "difficulty": "very-hard", "source": "JEE Main · JEE Advanced"},
  {"id": "math-trigonometry-40", "question": "The number of real solutions of sin x = x/10 is:", "options": ["6", "5", "7", "3"], "answer": 2, "explanation": "Solutions lie in [−10, 10]. For x ≥ 0: x = 0, one crossing in (π/2, π), and two in (2π, 3π), where the line stays below 1 at the hump x = 5π/2 ≈ 7.85. On (3π, 10], sin x < 0 < x/10. That makes 3 positive roots, 3 negative roots by oddness, and 0: 7 in all.", "difficulty": "very-hard", "source": "JEE Main · JEE Advanced"},
  {"id": "math-trigonometry-41", "question": "In a triangle ABC, cot(A/2) : cot(B/2) : cot(C/2) = 3 : 5 : 7. Then a : b : c equals:", "options": ["3 : 5 : 7", "4 : 5 : 6", "7 : 5 : 3", "6 : 5 : 4"], "answer": 3, "explanation": "cot(A/2) = (s − a)/r, so s − a : s − b : s − c = 3 : 5 : 7. Let them be 3k, 5k, 7k; adding gives s = 15k, so a = 12k, b = 10k, c = 8k, i.e. 6 : 5 : 4.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-trigonometry-42", "question": "The value of tan 20° tan 40° tan 80° is:", "options": ["1", "√3", "1/√3", "3"], "answer": 1, "explanation": "tan θ tan(60° − θ) tan(60° + θ) = tan 3θ. With θ = 20°: tan 20° tan 40° tan 80° = tan 60° = √3.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-trigonometry-43", "question": "Consider the following statements:\n(1) sin 18° = (√5 − 1)/4.\n(2) sin 18° · cos 36° = 1/4.\n(3) sin²72° − sin²60° = (√5 − 1)/8.\n(4) tan 36° · tan 54° = √3.\nHow many of these statements are correct?", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "(1) True. (2) True: (√5 − 1)(√5 + 1)/16 = 4/16 = 1/4. (3) True: sin²72° = cos²18° = (5 + √5)/8, and (5 + √5)/8 − 3/4 = (√5 − 1)/8. (4) False: tan 54° = cot 36°, so the product is 1. Three are correct.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-trigonometry-44", "question": "A 10 m flagstaff stands on a tower. From a point on the ground, the angles of elevation of the top and the bottom of the flagstaff are 60° and 45°. The height of the tower is:", "options": ["5(√3 + 1) m", "10(√3 + 1) m", "5(√3 − 1) m", "10√3 m"], "answer": 0, "explanation": "Let the tower be h m and the distance d. tan 45° = h/d gives d = h, and tan 60° = (h + 10)/h = √3. So h(√3 − 1) = 10 and h = 10/(√3 − 1) = 5(√3 + 1) m.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-trigonometry-45", "question": "The maximum value of cos x(sin x + cos x) is:", "options": ["√2", "(1 + √2)/2", "1", "(√2 − 1)/2"], "answer": 1, "explanation": "cos x sin x + cos²x = (sin 2x)/2 + (1 + cos 2x)/2 = 1/2 + (1/2)(sin 2x + cos 2x). Since sin 2x + cos 2x ≤ √2, the maximum is (1 + √2)/2.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-trigonometry-46", "question": "The value of tan 225° − cot 135° is:", "options": ["0", "−2", "2", "1"], "answer": 2, "explanation": "tan 225° = tan(180° + 45°) = 1 and cot 135° = cot(180° − 45°) = −1, so the value is 1 − (−1) = 2.", "difficulty": "easy", "source": "JEE Main pattern"},
  {"id": "math-trigonometry-47", "question": "In a triangle ABC, A = 30°, B = 45° and a = 2. Then b equals:", "options": ["2√2", "√2", "2√3", "4"], "answer": 0, "explanation": "By the sine rule, a/sin A = 2/(1/2) = 4, so b = 4 sin 45° = 4/√2 = 2√2.", "difficulty": "easy", "source": "JEE Main pattern"},
  {"id": "math-trigonometry-48", "question": "If tan θ = 3/4 and θ lies in the third quadrant, then sin θ + cos θ equals:", "options": ["7/5", "−1/5", "1/5", "−7/5"], "answer": 3, "explanation": "In the third quadrant both sine and cosine are negative: sin θ = −3/5 and cos θ = −4/5, so the sum is −7/5. Ignoring the quadrant gives 7/5.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "math-trigonometry-49", "question": "The fundamental period of f(x) = tan 3x + sin(x/2) is:", "options": ["π/3", "4π", "2π", "12π"], "answer": 1, "explanation": "tan 3x has period π/3 and sin(x/2) has period 4π. The period of the sum is the LCM of π/3 and 4π, which is 4π (4π is 12 times π/3).", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "math-trigonometry-50", "question": "If sin θ = 1/3, then sin 3θ equals:", "options": ["1", "23/27", "25/27", "1/9"], "answer": 1, "explanation": "sin 3θ = 3 sin θ − 4 sin³θ = 3(1/3) − 4(1/27) = 1 − 4/27 = 23/27.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "math-trigonometry-51", "question": "In any triangle ABC, b cos C + c cos B equals:", "options": ["b + c", "2R", "(b + c)/2", "a"], "answer": 3, "explanation": "This is the projection formula: side a is the sum of the projections of sides b and c on it, a = b cos C + c cos B.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "math-trigonometry-52", "question": "The general solution of cos 2x = cos x is (n an integer):", "options": ["x = 2nπ/3", "x = nπ", "x = 2nπ only", "x = nπ/3"], "answer": 0, "explanation": "cos 2x = cos x gives 2x = 2nπ ± x, i.e. x = 2nπ or x = 2nπ/3. The first family is contained in the second, so x = 2nπ/3. x = nπ fails at x = π: cos 2π = 1 but cos π = −1.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "math-trigonometry-53", "question": "The maximum value of sin x + sin(x + π/3) for real x is:", "options": ["2", "1", "√3", "√3/2"], "answer": 2, "explanation": "sin x + sin(x + π/3) = 2 sin(x + π/6) cos(π/6) = √3 sin(x + π/6), whose maximum is √3. 2 assumes both sines reach 1 together, which cannot happen.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-trigonometry-54", "question": "The value of sin²5° + sin²10° + sin²15° + … + sin²85° + sin²90° is:", "options": ["9", "17/2", "10", "19/2"], "answer": 3, "explanation": "Pair sin²k° with sin²(90 − k)° = cos²k°: each pair gives 1. The pairs (5, 85), …, (40, 50) give 8, sin²45° = 1/2 and sin²90° = 1. Total = 8 + 1/2 + 1 = 19/2.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-trigonometry-55", "question": "For the triangle with sides 5, 12 and 13, with exradii r₁, r₂, r₃ and inradius r, the value of r₁ + r₂ + r₃ − r is:", "options": ["28", "26", "13", "30"], "answer": 1, "explanation": "s = 15 and Δ = 30. r₁ = Δ/(s − a) = 3, r₂ = 30/3 = 10, r₃ = 30/2 = 15, r = Δ/s = 2. So r₁ + r₂ + r₃ − r = 26, which agrees with the identity r₁ + r₂ + r₃ − r = 4R (R = 13/2).", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-trigonometry-56", "question": "The angles of elevation of the top of a tower from two points on the ground at distances 4 m and 9 m from its foot, on the same straight line, are complementary. The height of the tower is:", "options": ["6.5 m", "5 m", "6 m", "√13 m"], "answer": 2, "explanation": "If the angles are θ and 90° − θ: tan θ = h/4 and tan(90° − θ) = cot θ = h/9. Multiplying, 1 = h²/36, so h = 6 m (the geometric mean of 4 and 9).", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-trigonometry-58", "question": "The maximum value of cos²(π/3 − x) − cos²(π/3 + x) is:", "options": ["√3/2", "1", "√3", "1/2"], "answer": 0, "explanation": "cos²P − cos²Q = sin(Q + P) sin(Q − P). With P = π/3 − x and Q = π/3 + x this is sin(2π/3) sin 2x = (√3/2) sin 2x, whose maximum is √3/2.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-trigonometry-59", "question": "A, B, C are the angles of a triangle with tan A = 1 and tan B = 2. Then tan C equals:", "options": ["−3", "1/3", "3", "−1"], "answer": 2, "explanation": "tan C = −tan(A + B) = −(1 + 2)/(1 − 1·2) = −3/(−1) = 3. As a check, tan A + tan B + tan C = 6 = tan A tan B tan C.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-trigonometry-60", "question": "In a triangle whose sides are 4, 5 and 6, the largest angle is:", "options": ["equal to the sum of the other two", "twice the smallest angle", "three times the smallest angle", "90°"], "answer": 1, "explanation": "Smallest angle A (opposite 4): cos A = (25 + 36 − 16)/(2·5·6) = 3/4. Largest angle C (opposite 6): cos C = (16 + 25 − 36)/(2·4·5) = 1/8. Since cos 2A = 2(9/16) − 1 = 1/8, C = 2A.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "math-trigonometry-61", "question": "If sin x + sin y = 1/2 and cos x + cos y = 1/3, then cos(x + y) equals:", "options": ["5/13", "12/13", "−12/13", "−5/13"], "answer": 3, "explanation": "Dividing the sum-to-product forms, 2 sin((x + y)/2)cos((x − y)/2) ÷ 2 cos((x + y)/2)cos((x − y)/2) gives tan((x + y)/2) = 3/2. Then cos(x + y) = (1 − 9/4)/(1 + 9/4) = −5/13.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-trigonometry-62", "question": "The value of cos(2π/7) + cos(4π/7) + cos(6π/7) is:", "options": ["1/2", "0", "−1/2", "−1"], "answer": 2, "explanation": "Multiply S by 2 sin(π/7): the products telescope as [sin(3π/7) − sin(π/7)] + [sin(5π/7) − sin(3π/7)] + [sin π − sin(5π/7)] = −sin(π/7). So 2 sin(π/7)·S = −sin(π/7) and S = −1/2.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-trigonometry-63", "question": "If sin x + sin²x = 1, then cos¹²x + 3cos¹⁰x + 3cos⁸x + cos⁶x equals:", "options": ["0", "2", "−1", "1"], "answer": 3, "explanation": "sin x = 1 − sin²x = cos²x. The expression is (cos⁴x + cos²x)³ = (sin²x + sin x)³ = 1³ = 1.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-trigonometry-64", "question": "The number of solutions of sin 2x + cos 2x + sin x + cos x + 1 = 0 in [0, 2π] is:", "options": ["4", "2", "3", "6"], "answer": 0, "explanation": "sin 2x + 1 = (sin x + cos x)² and cos 2x = (cos x − sin x)(cos x + sin x), so the left side factors as (sin x + cos x)(2 cos x + 1). sin x + cos x = 0 gives 3π/4, 7π/4; cos x = −1/2 gives 2π/3, 4π/3. Total 4.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-trigonometry-65", "question": "For an arbitrary triangle ABC, how many of the following are correct?\n(1) sin 2A + sin 2B + sin 2C = 4 sin A sin B sin C.\n(2) tan A + tan B + tan C = tan A tan B tan C (no angle a right angle).\n(3) cos²A + cos²B + cos²C = 1 + 2 cos A cos B cos C.\n(4) cot A cot B + cot B cot C + cot C cot A = 1.", "options": ["Only one", "Only three", "Only two", "All four"], "answer": 1, "explanation": "(1), (2) and (4) are standard identities for A + B + C = π. (3) has the wrong sign: the identity is cos²A + cos²B + cos²C = 1 − 2 cos A cos B cos C (check an equilateral triangle: 3/4 = 1 − 1/4). So three are correct.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-trigonometry-66", "question": "From a point 10 m above the surface of a still lake, the angle of elevation of a cloud is 30° and the angle of depression of its reflection in the lake is 60°. The height of the cloud above the lake is:", "options": ["30 m", "10√3 m", "15 m", "20 m"], "answer": 3, "explanation": "Let the cloud be h above the lake and x away horizontally. tan 30° = (h − 10)/x and tan 60° = (h + 10)/x (the reflection is h below the lake). Dividing: (h + 10)/(h − 10) = 3, so h = 20 m.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-trigonometry-67", "question": "If sin θ and cos θ are the roots of ax² + bx + c = 0 (a ≠ 0), then:", "options": ["b² − a² = 2ac", "a² − b² = 2ac", "b² + a² = 2ac", "b² − a² = 4ac"], "answer": 0, "explanation": "sin θ + cos θ = −b/a and sin θ cos θ = c/a. Squaring the first: 1 + 2 sin θ cos θ = b²/a², so 1 + 2c/a = b²/a², i.e. a² + 2ac = b².", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-trigonometry-68", "question": "If cos(α + β) = 4/5 and sin(α − β) = 5/13, where 0 < α, β < π/4, then tan 2α equals:", "options": ["33/56", "56/33", "16/63", "63/16"], "answer": 1, "explanation": "α + β is in (0, π/2), so tan(α + β) = 3/4; α − β is in (−π/4, π/4), so tan(α − β) = 5/12. tan 2α = tan[(α + β) + (α − β)] = (3/4 + 5/12)/(1 − 15/48) = (7/6)/(33/48) = 56/33.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-trigonometry-69", "question": "In a triangle ABC, a = 2b and A = 3B. Then the angle A is:", "options": ["60°", "120°", "90°", "135°"], "answer": 2, "explanation": "By the sine rule, sin 3B/sin B = a/b = 2, so 3 − 4 sin²B = 2 and sin B = 1/2, B = 30° (B = 150° is impossible since A = 3B). Then A = 90°.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-trigonometry-70", "question": "The number of real solutions of sin(eˣ) = 5ˣ + 5⁻ˣ is:", "options": ["1", "0", "2", "infinitely many"], "answer": 1, "explanation": "By AM ≥ GM, 5ˣ + 5⁻ˣ ≥ 2 for every real x, while sin(eˣ) ≤ 1. The two sides can never be equal, so there is no solution.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"math-trigonometry-71","question":"The number of solutions of sin x + sin 2x + sin 3x = 0 in the closed interval [0, 2π] is:","options":["7","6","5","8"],"answer":0,"explanation":"sin x + sin 3x = 2 sin 2x cos x, so the equation is sin 2x(2cos x + 1) = 0. sin 2x = 0 gives x = 0, π/2, π, 3π/2, 2π (5 values) and cos x = −1/2 gives 2π/3, 4π/3, for 7 in all (forgetting the endpoint 2π, or one factor, gives the smaller options).","difficulty":"hard","source":"JEE Main pattern"},
  {"id": "math-trigonometry-72", "question": "The number of solutions of cos²x + cos²2x + cos²3x = 1 in [0, π] is:", "options": ["4", "5", "6", "7"], "answer": 1, "explanation": "Using cos²x + cos²2x + cos²3x − 1 = 2cos x cos 2x cos 3x, the equation becomes cos x cos 2x cos 3x = 0. cos x = 0 gives π/2; cos 2x = 0 gives π/4, 3π/4; cos 3x = 0 gives π/6, π/2, 5π/6. π/2 appears twice, so there are 5 distinct solutions (6 is the double-count trap).", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id":"math-trigonometry-73","question":"For 0 < x < π/2, the least value of 9 sec²x + 16 cosec²x is:","options":["25","24","49","48"],"answer":2,"explanation":"9 sec²x + 16 cosec²x = 9 + 16 + 9 tan²x + 16 cot²x ≥ 25 + 2√(9 × 16) = 25 + 24 = 49, with equality when tan²x = 4/3. Applying AM–GM to the original two terms gives 2√(144 sec²x cosec²x), which is not constant — that misuse leads to 24.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"math-trigonometry-74","question":"The value of (tan 70° − tan 20°)/tan 50° is:","options":["1","1/2","√3","2"],"answer":3,"explanation":"Since 70° − 20° = 50°, tan 50° = (tan 70° − tan 20°)/(1 + tan 70° tan 20°), and tan 70° tan 20° = tan 70° cot 70° = 1. So tan 70° − tan 20° = 2 tan 50° and the ratio is 2.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"math-trigonometry-75","question":"The value of cos(π/15)·cos(2π/15)·cos(4π/15)·cos(8π/15) is:","options":["−1/16","1/32","−1/8","1/16"],"answer":0,"explanation":"Multiply and divide by 2⁴ sin(π/15) and use 2 sin θ cos θ = sin 2θ four times: the product is sin(16π/15)/(16 sin(π/15)). Since sin(16π/15) = −sin(π/15), the value is −1/16 (cos(8π/15) is negative, which the trap +1/16 misses).","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"math-trigonometry-76","question":"The value of Σ (k = 1 to 89) 1/(1 + tan k°) is:","options":["44","44.5","45","89/4"],"answer":1,"explanation":"Pair k with 90 − k: 1/(1 + tan k°) + 1/(1 + cot k°) = 1/(1 + t) + t/(t + 1) = 1. The 44 pairs (k = 1 to 44 with 89 to 46) give 44, and the middle term k = 45 gives 1/2, so the sum is 44.5.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id": "math-trigonometry-77", "question": "The three exradii of a triangle are 2, 3 and 6. The area of the triangle is:", "options": ["12", "36", "√6", "6"], "answer": 3, "explanation": "With rₖ = Δ/(s − a) etc., 1/r₁ + 1/r₂ + 1/r₃ = (3s − 2s)/Δ = s/Δ = 1/r, so r = 1/(1/2 + 1/3 + 1/6) = 1. Also Δ² = r·r₁r₂r₃ = 1 × 36, so Δ = 6 (the sides work out as 3, 4, 5); 36 is Δ², not Δ.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "math-trigonometry-78", "question": "In triangle ABC, b = 8, a = 6 and A = 30°. Two triangles satisfy these data. The two possible values of the side c differ by:", "options": ["2√5", "8√3", "4√5", "2√7"], "answer": 2, "explanation": "Since b sin A = 4 < a = 6 < b = 8, the ambiguous case gives two triangles. From a² = b² + c² − 2bc cos A: 36 = 64 + c² − 8√3c, so c² − 8√3c + 28 = 0 with roots 4√3 ± 2√5. They differ by 4√5 (8√3 is their sum).", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "math-trigonometry-79", "question": "A, B, C are three points on level ground on a straight line through the foot of a tower, all on the same side of it, in that order towards the tower. The angles of elevation of the top of the tower from A, B, C are 30°, 45° and 60°. Then AB : BC equals:", "options": ["1 : 1", "2 : 1", "3 : 1", "√3 : 1"], "answer": 3, "explanation": "With height h, the distances from the foot are h√3, h and h/√3. So AB = h(√3 − 1) and BC = h(1 − 1/√3) = h(√3 − 1)/√3, giving AB : BC = √3 : 1, not 1 : 1 as equal 15° steps might suggest.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"math-trigonometry-80","question":"The shadow of a vertical tower is 40 m longer when the Sun's elevation is 30° than when it is 60°. The height of the tower is:","options":["20√3 m","20 m","40√3 m","10√3 m"],"answer":0,"explanation":"The shadow lengths are h cot 30° = h√3 and h cot 60° = h/√3. Their difference h(√3 − 1/√3) = 2h/√3 = 40 gives h = 20√3 m ≈ 34.6 m.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id": "math-trigonometry-81", "question": "How many of the following hold for every triangle ABC?\n(1) cos²A + cos²B + cos²C + 2cos A cos B cos C = 1.\n(2) tan(A/2)tan(B/2) + tan(B/2)tan(C/2) + tan(C/2)tan(A/2) = 1.\n(3) cos A + cos B + cos C ≤ 3/2.\n(4) sin A + sin B + sin C ≤ 3/2.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "(1) and (2) are standard identities for A + B + C = π. (3) cos A + cos B + cos C = 1 + r/R ≤ 3/2 since R ≥ 2r: true. (4) is false: an equilateral triangle gives 3·(√3/2) = 3√3/2 ≈ 2.6 > 3/2 (that is the actual maximum). So exactly three hold.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "math-trigonometry-82", "question": "The value of tan 7.5° is:", "options": ["√6 + √3 − √2 − 2", "√6 − √3 + √2 − 2", "√6 − √3 − √2 + 2", "√6 + √3 + √2 − 2"], "answer": 1, "explanation": "tan(θ/2) = (1 − cos θ)/sin θ with θ = 15°: cos 15° = (√6 + √2)/4 and sin 15° = (√6 − √2)/4, so tan 7.5° = (4 − √6 − √2)/(√6 − √2). Rationalising, ((4 − √6 − √2)(√6 + √2))/4 = (4√6 + 4√2 − 8 − 4√3)/4 = √6 − √3 + √2 − 2 ≈ 0.1317.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id":"math-trigonometry-83","question":"The sum of all solutions of tan x + tan 2x + tan x·tan 2x = 1 in [0, π] is:","options":["3π/4","5π/4","π/2","π/4"],"answer":2,"explanation":"Rearranged, tan x + tan 2x = 1 − tan x tan 2x, so tan 3x = 1 when 1 − tan x tan 2x ≠ 0, giving x = π/12 + nπ/3: π/12, 5π/12, 3π/4 in [0, π]. But at x = 3π/4, tan 2x = tan(3π/2) is undefined, so it must be rejected; the sum is π/12 + 5π/12 = π/2 (keeping 3π/4 gives the trap 5π/4).","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"math-trigonometry-84","question":"The greatest value of sin x + √3 cos x + 2 cos(x + π/6) over real x is:","options":["4","2√2","2 + √3","2√3"],"answer":3,"explanation":"sin x + √3 cos x = 2 cos(x − π/6), so the expression is 2[cos(x − π/6) + cos(x + π/6)] = 4 cos x cos(π/6) = 2√3 cos x. Its maximum is 2√3; adding the separate maxima 2 + 2 = 4 ignores that they occur at different x.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"math-trigonometry-85","question":"If cos x + cos y + cos z = 0 and sin x + sin y + sin z = 0, then cos(x − y) + cos(y − z) + cos(z − x) equals:","options":["−3/2","0","3/2","−1"],"answer":0,"explanation":"Squaring and adding the two conditions: (Σcos)² + (Σsin)² = 3 + 2[cos(x − y) + cos(y − z) + cos(z − x)] = 0. So the required sum is −3/2 (0 is the value of cos 2x + cos 2y + cos 2z, a different classic result).","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id": "math-trigonometry-86", "question": "In triangle ABC, (a² + b²) sin(A − B) = (a² − b²) sin(A + B). Then the triangle is:", "options": ["necessarily isosceles", "necessarily right-angled", "either isosceles or right-angled", "necessarily equilateral"], "answer": 2, "explanation": "Expanding, a²[sin(A − B) − sin(A + B)] + b²[sin(A − B) + sin(A + B)] = 0, i.e. −2a² cos A sin B + 2b² sin A cos B = 0. With a = 2R sin A, b = 2R sin B this becomes sin A sin B (sin 2B − sin 2A) = 0, so 2A = 2B or 2A = π − 2B: A = B or A + B = 90°. Either case is possible.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id":"math-trigonometry-87","question":"In triangle ABC, b = 5, c = 7 and the median from A has length 2√7. The area of the triangle is:","options":["12√6","6√6","√6","14"],"answer":1,"explanation":"By Apollonius, 4·AD² = 2b² + 2c² − a²: 112 = 50 + 98 − a², so a = 6. The sides 5, 6, 7 give s = 9 and Δ = √(9 × 4 × 3 × 2) = √216 = 6√6.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id": "math-trigonometry-88", "question": "The number of solutions of |sin x| = |cos 3x| in [0, π] is:", "options": ["4", "5", "6", "8"], "answer": 2, "explanation": "Squaring, (1 − cos 2x)/2 = (1 + cos 6x)/2, so cos 6x + cos 2x = 0, i.e. 2cos 4x cos 2x = 0. cos 2x = 0 gives π/4, 3π/4 and cos 4x = 0 gives π/8, 3π/8, 5π/8, 7π/8, all distinct: 6 solutions.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"math-trigonometry-89","question":"A, B, C are the angles of a triangle and tan A, tan B, tan C are all positive integers. Then tan A·tan B·tan C equals:","options":["3","Cannot be determined","9","6"],"answer":3,"explanation":"In a triangle tan A + tan B + tan C = tan A tan B tan C. For positive integers p ≤ q ≤ r with p + q + r = pqr, r = (p + q)/(pq − 1) forces p = 1, q = 2, r = 3 (p ≥ 2 makes pqr > p + q + r). So the product is 6.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"math-trigonometry-90","question":"If 3 sin x + 4 cos x = 5, then 4 sin x − 3 cos x equals:","options":["0","5","1","−5"],"answer":0,"explanation":"(3 sin x + 4 cos x)² + (4 sin x − 3 cos x)² = 9 + 16 = 25 for every x (the cross terms cancel). With the first bracket equal to 5, the second must be 0.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"math-trigonometry-91","question":"The value of sin 20° sin 40° sin 60° sin 80° is:","options":["1/16","3/16","√3/8","3/8"],"answer":1,"explanation":"sin 20° sin 40° sin 80° = sin 20° sin(60° − 20°) sin(60° + 20°) = (1/4) sin 60° = √3/8. Multiplying by sin 60° = √3/2 gives 3/16 (√3/8 forgets that factor).","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"math-trigonometry-92","question":"A triangle has circumradius 5 and inradius 2. The distance between its circumcentre and incentre is:","options":["3","√21","√5","1"],"answer":2,"explanation":"Euler's relation gives OI² = R² − 2Rr = 25 − 20 = 5, so OI = √5. (3 = R − r and √21 = √(R² − r²) are the usual misremembered forms.)","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"math-trigonometry-93","question":"In triangle ABC, sin²A + sin²B + sin²C = 2. Then the triangle is:","options":["equilateral","isosceles but not right-angled","obtuse-angled","right-angled"],"answer":3,"explanation":"For any triangle, sin²A + sin²B + sin²C = 2 + 2cos A cos B cos C. Equality with 2 needs cos A cos B cos C = 0, so one angle is 90°.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"math-trigonometry-94","question":"If sin x + cos x = 1/5 and 0 < x < π, then tan x equals:","options":["−4/3","4/3","−3/4","3/4"],"answer":0,"explanation":"Squaring, 1 + 2 sin x cos x = 1/25, so sin x cos x = −12/25 < 0 and x is in (π/2, π), where sin x > 0 > cos x. Then sin x and cos x are roots of t² − t/5 − 12/25 = 0, i.e. 4/5 and −3/5, so tan x = −4/3 (−3/4 swaps sin and cos).","difficulty":"hard","source":"JEE Main pattern"},
  {"id": "math-trigonometry-95", "question": "From the top of a tower, the angles of depression of two points on level ground on opposite sides of the tower, in line with its foot, are 30° and 45°. If the points are 100 m apart, the height of the tower is:", "options": ["50(√3 + 1) m", "50(√3 − 1) m", "100(√3 − 1) m", "50√3 m"], "answer": 1, "explanation": "The points are h cot 30° = h√3 and h cot 45° = h from the foot, on opposite sides, so h(√3 + 1) = 100 and h = 100/(√3 + 1) = 50(√3 − 1) ≈ 36.6 m. Taking them on the same side would give h(√3 − 1) = 100 and the trap 50(√3 + 1).", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id":"math-trigonometry-96","question":"The value of sin 75° · cos 75° is:","options":["1/4","1/2","√3/4","(2 + √3)/4"],"answer":0,"explanation":"sin θ cos θ = (1/2) sin 2θ, so sin 75° cos 75° = (1/2) sin 150° = (1/2)(1/2) = 1/4.","difficulty":"easy","source":"JEE Main"},
  {"id":"math-trigonometry-97","question":"The value of cos 1° · cos 2° · cos 3° · … · cos 179° is:","options":["1","−1","−1/2","0"],"answer":3,"explanation":"One of the factors is cos 90° = 0, so the whole product is 0. No pairing or sign analysis is needed.","difficulty":"easy","source":"JEE Main"},
  {"id":"math-trigonometry-98","question":"If sec θ + tan θ = 3, then sin θ equals:","options":["3/5","4/5","2/3","1/3"],"answer":1,"explanation":"Since sec²θ − tan²θ = 1, sec θ − tan θ = 1/3. Adding and subtracting: sec θ = 5/3 and tan θ = 4/3. Hence sin θ = tan θ/sec θ = 4/5.","difficulty":"moderate","source":"JEE Main"},
  {"id":"math-trigonometry-99","question":"For all real x, sin²x + sin²(x + π/3) + sin²(x − π/3) equals:","options":["1","3/2","3/4","a value that depends on x"],"answer":1,"explanation":"Using sin²θ = (1 − cos 2θ)/2, the sum is 3/2 − [cos 2x + cos(2x + 2π/3) + cos(2x − 2π/3)]/2. The three cosines are at angles 2π/3 apart, so they add to 0, leaving the constant 3/2.","difficulty":"moderate","source":"JEE Main"},
  {"id":"math-trigonometry-100","question":"In a triangle ABC, b = 6, c = 8 and A = 150°. The area of the triangle is:","options":["24","12√3","6","12"],"answer":3,"explanation":"Area = (1/2) bc sin A = (1/2)(6)(8) sin 150° = 24 × 1/2 = 12.","difficulty":"moderate","source":"JEE Main"},
  {"id":"math-trigonometry-101","question":"The number of solutions of 2cos²x + 3 sin x = 0 in [0, 2π] is:","options":["2","4","1","3"],"answer":0,"explanation":"Writing cos²x = 1 − sin²x gives 2sin²x − 3 sin x − 2 = 0, i.e. (2 sin x + 1)(sin x − 2) = 0. Only sin x = −1/2 is possible, giving x = 7π/6 and 11π/6: two solutions.","difficulty":"moderate","source":"JEE Main"},
  {"id":"math-trigonometry-102","question":"Wherever defined, sin 3x/sin x − cos 3x/cos x equals:","options":["1","2 cos 2x","2","4 cos 2x"],"answer":2,"explanation":"Combine: (sin 3x cos x − cos 3x sin x)/(sin x cos x) = sin(3x − x)/(sin x cos x) = sin 2x/(sin x cos x) = 2.","difficulty":"moderate","source":"JEE Main"},
  {"id":"math-trigonometry-103","question":"The value of sin 10° + sin 50° − sin 70° is:","options":["1/2","√3/2","1","0"],"answer":3,"explanation":"sin 50° − sin 70° = 2 cos 60° sin(−10°) = −sin 10°. Hence sin 10° + sin 50° − sin 70° = 0. This is the identity sin θ + sin(60° − θ) = sin(60° + θ) at θ = 10°.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-trigonometry-104","question":"A triangle has circumradius 10 and inradius 3. Then cos A + cos B + cos C equals:","options":["7/10","3/10","13/10","23/20"],"answer":2,"explanation":"For every triangle, cos A + cos B + cos C = 1 + r/R. Here that is 1 + 3/10 = 13/10, whatever the actual sides are.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-trigonometry-105","question":"Over all acute-angled triangles ABC, the least value of tan A + tan B + tan C is:","options":["3","3√3","√3","9"],"answer":1,"explanation":"In a triangle tan A + tan B + tan C = tan A tan B tan C = p. For an acute triangle all tangents are positive, so by AM–GM p ≥ 3p^(1/3), i.e. p² ≥ 27 and p ≥ 3√3. Equality holds for the equilateral triangle (tan 60° = √3).","difficulty":"hard","source":"JEE Main"},
  {"id":"math-trigonometry-106","question":"The number of solutions of sin 5x = sin x in [0, π] is:","options":["5","6","4","3"],"answer":0,"explanation":"sin 5x − sin x = 2 cos 3x sin 2x = 0. sin 2x = 0 gives 0, π/2, π; cos 3x = 0 gives π/6, π/2, 5π/6. π/2 appears in both lists, so there are 5 distinct solutions.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-trigonometry-107","question":"From a point A on level ground the angle of elevation of the top of a tower is 15°. After walking 100 m straight towards the tower, the angle of elevation becomes 30°. The height of the tower is:","options":["50 m","50√3 m","100 m","25(√3 + 1) m"],"answer":0,"explanation":"Let B be the new point and T the top. In triangle ABT the exterior angle at B is 30° = 15° + ∠ATB, so ∠ATB = 15° and BT = AB = 100 m. The height is BT sin 30° = 50 m, with no need for tan 15°.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-trigonometry-108","question":"The number of solutions of sin x + sin 3x + sin 5x = 0 in [0, π] is:","options":["6","4","5","3"],"answer":1,"explanation":"sin x + sin 5x = 2 sin 3x cos 2x, so the equation is sin 3x (2 cos 2x + 1) = 0. sin 3x = 0 gives 0, π/3, 2π/3, π; cos 2x = −1/2 gives π/3, 2π/3 again. Only 4 distinct solutions.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-trigonometry-109","question":"In a triangle ABC, b = 3, c = 6 and A = 120°. The length of the bisector of angle A (from A to BC) is:","options":["3","4","2","√7"],"answer":2,"explanation":"Splitting the area: (1/2)bc sin A = (1/2)b·ℓ sin(A/2) + (1/2)c·ℓ sin(A/2) gives ℓ = 2bc cos(A/2)/(b + c). Here ℓ = 2 × 18 × cos 60°/9 = 2.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-trigonometry-110","question":"The value of Σ (k = 1 to 6) cos²(kπ/7) is:","options":["3","7/2","2","5/2"],"answer":3,"explanation":"cos²θ = (1 + cos 2θ)/2, so the sum is 3 + (1/2)Σ cos(2kπ/7) for k = 1 to 6. The non-trivial 7th roots of unity have real parts adding to −1, so the sum is 3 − 1/2 = 5/2.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-trigonometry-111","question":"The least positive x satisfying sin 2x = cos 3x is:","options":["π/6","π/5","π/10","π/2"],"answer":2,"explanation":"Write sin 2x = cos(π/2 − 2x). Then 3x = 2nπ ± (π/2 − 2x), giving x = π/10 + 2nπ/5 or x = 2nπ − π/2. The least positive value is π/10.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-trigonometry-112","question":"The greatest value of (sin x + cos x)(sin x + 3 cos x) over real x is:","options":["2 + √5","4","3 + √2","2 + √3"],"answer":0,"explanation":"Expand: sin²x + 4 sin x cos x + 3cos²x = 1 + 2cos²x + 2 sin 2x = 2 + cos 2x + 2 sin 2x. Since cos 2x + 2 sin 2x has maximum √(1 + 4) = √5, the greatest value is 2 + √5.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-trigonometry-113","question":"In a triangle ABC, sin A : sin B : sin C = 4 : 5 : 6. Then cos A : cos B : cos C equals:","options":["2 : 9 : 12","6 : 5 : 4","9 : 12 : 2","12 : 9 : 2"],"answer":3,"explanation":"By the sine rule a : b : c = 4 : 5 : 6. The cosine rule gives cos A = (25 + 36 − 16)/60 = 3/4, cos B = (16 + 36 − 25)/48 = 9/16 and cos C = (16 + 25 − 36)/40 = 1/8. Multiplying by 16: 12 : 9 : 2.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-trigonometry-114","question":"The range of sin⁶x + cos⁶x over real x is:","options":["[1/2, 1]","[1/4, 1]","[0, 1]","[1/8, 1]"],"answer":1,"explanation":"sin⁶x + cos⁶x = (sin²x + cos²x)³ − 3sin²x cos²x(sin²x + cos²x) = 1 − (3/4) sin²2x. As sin²2x runs over [0, 1], the expression runs over [1/4, 1].","difficulty":"hard","source":"JEE Main"},
  {"id":"math-trigonometry-115","question":"The value of cot 10° − 4 cos 10° is:","options":["1","√3","2","1/√3"],"answer":1,"explanation":"cot 10° − 4 cos 10° = (cos 10° − 2 sin 20°)/sin 10°. Now cos 10° − 2 sin 20° = (sin 80° − sin 20°) − sin 20° = cos 50° − sin 20° = sin 40° − sin 20° = 2 cos 30° sin 10° = √3 sin 10°. So the value is √3.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-trigonometry-116","question":"The value of sin(π/7) · sin(2π/7) · sin(3π/7) · sin(4π/7) · sin(5π/7) · sin(6π/7) is:","options":["1/64","7/128","√7/8","7/64"],"answer":3,"explanation":"From zⁿ − 1 = Π(z − ωₖ), dividing by z − 1 and letting z → 1 gives Π|1 − ωₖ| = n, and |1 − e^(2ikπ/n)| = 2 sin(kπ/n). So Π sin(kπ/n) for k = 1 to n − 1 equals n/2ⁿ⁻¹ = 7/64 for n = 7.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-trigonometry-117","question":"The value of tan(π/7) · tan(2π/7) · tan(3π/7) is:","options":["√7","7","1","√3"],"answer":0,"explanation":"Π sin(kπ/7) for k = 1, 2, 3 is √7/8 (the square root of 7/2⁶), and Π cos(kπ/7) for k = 1, 2, 3 is 1/8 (since cos(π/7)cos(2π/7)cos(4π/7) = −1/8 and cos(3π/7) = −cos(4π/7)). Dividing, the product of tangents is √7.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-trigonometry-118","question":"The value of (1 + tan 1°)(1 + tan 2°)(1 + tan 3°)…(1 + tan 45°) is:","options":["2²²","2⁴⁵","2²³","2⁴⁴"],"answer":2,"explanation":"If A + B = 45°, then (1 + tan A)(1 + tan B) = 2. Pair 1° with 44°, 2° with 43°, …, 22° with 23°: 22 pairs give 2²², and the leftover factor 1 + tan 45° = 2. The product is 2²³.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-trigonometry-119","question":"The value of cos(π/11) + cos(3π/11) + cos(5π/11) + cos(7π/11) + cos(9π/11) is:","options":["−1/2","0","1","1/2"],"answer":3,"explanation":"Multiply by 2 sin(π/11) and use 2 sin A cos B = sin(A + B) − sin(B − A): the sum telescopes to sin(10π/11). So the expression is sin(10π/11)/(2 sin(π/11)) = 1/2, since sin(10π/11) = sin(π/11).","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-trigonometry-120","question":"The number of real x satisfying sin x · sin 2x · sin 3x = 1 is:","options":["1","2","0","infinitely many"],"answer":2,"explanation":"Each factor has modulus at most 1, so the product can equal 1 only if |sin x| = |sin 2x| = |sin 3x| = 1. But |sin 2x| = 1 forces x = π/4 + kπ/2, where |sin x| = 1/√2 < 1. So there is no solution.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-trigonometry-121","question":"The product of the three exradii of the triangle with sides 9, 10 and 17 is:","options":["324","648","1296","72"],"answer":1,"explanation":"r₁r₂r₃ = Δ³/[(s − a)(s − b)(s − c)] = Δ³·s/Δ² = Δs. Here s = 18 and Δ = √(18 × 9 × 8 × 1) = 36, so the product is 36 × 18 = 648.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-trigonometry-122","question":"The number of solutions of 2 cos x = |sin x| in [0, 2π] is:","options":["2","4","1","3"],"answer":0,"explanation":"The right side is ≥ 0, so cos x ≥ 0 and x is in the first or fourth quadrant (cos x = 0 fails since then |sin x| = 1). There the equation is tan x = 2 (first quadrant) or tan x = −2 (fourth quadrant), one solution each: 2 in all.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-trigonometry-123","question":"The number of values of θ in (0, π) for which sin θ, sin 2θ, sin 3θ are in arithmetic progression is:","options":["1","0","2","3"],"answer":0,"explanation":"AP means sin θ + sin 3θ = 2 sin 2θ, i.e. 2 sin 2θ cos θ = 2 sin 2θ, so sin 2θ (cos θ − 1) = 0. In (0, π), cos θ ≠ 1, and sin 2θ = 0 only at θ = π/2 (giving 1, 0, −1). Exactly one value.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-trigonometry-124","question":"The least positive x satisfying tan x · tan(π/3 − x) · tan(π/3 + x) = √3 is:","options":["π/3","π/9","π/18","2π/9"],"answer":1,"explanation":"The identity tan x tan(60° − x) tan(60° + x) = tan 3x turns the equation into tan 3x = √3, so 3x = π/3 + nπ and x = π/9 + nπ/3. The least positive value is π/9, where all three tangents are defined.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-trigonometry-125","question":"The value of cos²(π/5) + cos²(2π/5) is:","options":["1","1/2","3/4","5/4"],"answer":2,"explanation":"cos 36° = (√5 + 1)/4 and cos 72° = (√5 − 1)/4. Their squares are (6 + 2√5)/16 and (6 − 2√5)/16, whose sum is 12/16 = 3/4.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-trigonometry-126","question":"If x + y = 2π/3 with x, y real, the greatest value of sin x · sin y is:","options":["1/4","1","1/2","3/4"],"answer":3,"explanation":"sin x sin y = [cos(x − y) − cos(x + y)]/2 = [cos(x − y) + 1/2]/2. This is greatest when x = y = π/3, giving (1 + 1/2)/2 = 3/4.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-trigonometry-127","question":"In a triangle ABC, A = 60°, a = 7 and b + c = 13. The area of the triangle is:","options":["20√3","40","10√3","10"],"answer":2,"explanation":"Cosine rule: 49 = b² + c² − bc = (b + c)² − 3bc = 169 − 3bc, so bc = 40. Area = (1/2) bc sin 60° = 20 × √3/2 = 10√3 (the triangle is 5, 7, 8).","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-trigonometry-128","question":"A triangle has inradius 1, circumradius 4 and semi-perimeter 8. Then ab + bc + ca equals:","options":["81","64","65","97"],"answer":0,"explanation":"The sides are the roots of x³ − 2sx² + (s² + r² + 4Rr)x − 4Rrs = 0, so ab + bc + ca = s² + r² + 4Rr = 64 + 1 + 16 = 81. (Check: abc = 4RΔ = 4Rrs = 128.)","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-trigonometry-129","question":"The value of 4 cos 12° · cos 48° · cos 72° is:","options":["(√5 − 1)/4","1/2","1/4","(√5 + 1)/4"],"answer":3,"explanation":"Use cos θ cos(60° − θ) cos(60° + θ) = (1/4) cos 3θ with θ = 12°: cos 12° cos 48° cos 72° = (1/4) cos 36°. So 4 × that = cos 36° = (√5 + 1)/4.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-trigonometry-130","question":"The number of solutions of sin x + cos x = 1 + sin 2x in the closed interval [0, 2π] is:","options":["4","3","5","6"],"answer":2,"explanation":"Put t = sin x + cos x, so sin 2x = t² − 1 and the equation becomes t = t², i.e. t = 0 or t = 1. t = 0 gives x = 3π/4, 7π/4; t = 1 gives x = 0, π/2, 2π. That is 5 solutions; forgetting that both endpoints 0 and 2π count gives 4.","difficulty":"very-hard","source":"JEE Advanced"},
  {"id":"math-trigonometry-131","question":"In triangle ABC, A = 45°, a = 2 and b = √6. The sum of all possible values of c is:","options":["√3 + 1","2√3","2","√6"],"answer":1,"explanation":"The cosine rule gives c² − 2√3c + 2 = 0, so c = √3 ± 1; both are positive, and sin B = √3/2 allows B = 60° or 120° (the ambiguous case). Their sum is 2√3. Taking only the acute B gives √3 + 1; 2 is the difference of the two values.","difficulty":"very-hard","source":"JEE Advanced"},
  {"id":"math-trigonometry-132","question":"A 10 m flagstaff stands on top of a tower. From a point on the ground, the angles of elevation of the bottom and the top of the flagstaff are 45° and 60°. The height of the tower is:","options":["10√3 m","5√3 m","10(√3 + 1) m","5(√3 + 1) m"],"answer":3,"explanation":"With tower height h, the 45° angle puts the point at distance h. Then tan 60° = (h + 10)/h, so √3h = h + 10 and h = 10/(√3 − 1) = 5(√3 + 1) ≈ 13.66 m. Forgetting the division by 2 when rationalising gives 10(√3 + 1).","difficulty":"hard","source":"JEE Main"},
  {"id":"math-trigonometry-133","question":"The value of sin 12° · sin 48° · sin 54° is:","options":["1/8","1/4","1/16","√3/8"],"answer":0,"explanation":"sin 12° sin 48° = (cos 36° − cos 60°)/2 = (cos 36° − 1/2)/2, and cos 36° − 1/2 = (√5 − 1)/4 = sin 18°. Then sin 18° · sin 54° = sin 18° cos 36° = 1/4, so the product is (1/2)(1/4) = 1/8.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-trigonometry-134","question":"The number of solutions of |cos x| = sin x in [0, 4π] is:","options":["2","8","6","4"],"answer":3,"explanation":"sin x must be non-negative, so x ∈ [0, π] ∪ [2π, 3π]. Where cos x ≥ 0 we need tan x = 1, and where cos x < 0 we need tan x = −1: x = π/4, 3π/4, 9π/4, 11π/4. Ignoring the sign of sin x would wrongly give 8.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-trigonometry-135","question":"The number of solutions of cos x + cos 3x = cos 2x in [0, 2π] is:","options":["6","4","2","8"],"answer":0,"explanation":"cos x + cos 3x = 2 cos 2x cos x, so cos 2x(2 cos x − 1) = 0. cos 2x = 0 gives π/4, 3π/4, 5π/4, 7π/4, and cos x = 1/2 gives π/3, 5π/3. Total 6; dividing by cos 2x loses four of them.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-trigonometry-136","question":"In a triangle with sides 3, 5 and 7, the largest angle is:","options":["150°","120°","135°","60°"],"answer":1,"explanation":"The largest angle is opposite the side 7: cos C = (9 + 25 − 49)/(2·3·5) = −15/30 = −1/2, so C = 120°. Dropping the minus sign gives 60°.","difficulty":"moderate","source":"JEE Main"},
  {"id":"math-trigonometry-137","question":"In triangle ABC, cot(A/2) : cot(B/2) : cot(C/2) = 2 : 3 : 4. Then a : b : c equals:","options":["5 : 6 : 7","2 : 3 : 4","7 : 6 : 5","4 : 3 : 2"],"answer":2,"explanation":"cot(A/2) = (s − a)/r, so s − a : s − b : s − c = 2 : 3 : 4. Adding, s = 9 (in those units), so a = 7, b = 6, c = 5. A larger half-angle cotangent means a smaller angle, which is why the order reverses.","difficulty":"very-hard","source":"JEE Advanced"},
  {"id":"math-trigonometry-138","question":"The least value of 4 sin²x + 9 cosec²x over real x (where defined) is:","options":["12","6","15","13"],"answer":3,"explanation":"With t = sin²x ∈ (0, 1], g(t) = 4t + 9/t is decreasing on (0, 3/2), so its least value on (0, 1] is g(1) = 13. AM–GM gives 12, but equality would need t = 3/2, which is impossible.","difficulty":"very-hard","source":"JEE Advanced"},
  {"id":"math-trigonometry-139","question":"The value of tan 10° · tan 50° · tan 70° is:","options":["√3","1/√3","1","√3/2"],"answer":1,"explanation":"tan θ · tan(60° − θ) · tan(60° + θ) = tan 3θ. With θ = 10° the product is tan 30° = 1/√3. The similar product tan 20° tan 40° tan 80° equals tan 60° = √3, which is the trap.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-trigonometry-140","question":"Wherever defined, cosec 2θ + cosec 4θ + cosec 8θ + cosec 16θ equals:","options":["cot θ − cot 16θ","cot 2θ − cot 32θ","cot θ − cot 32θ","tan 16θ − tan θ"],"answer":0,"explanation":"cot x − cot 2x = sin x/(sin x sin 2x) = cosec 2x. So cosec 2θ = cot θ − cot 2θ, cosec 4θ = cot 2θ − cot 4θ, and so on; the sum telescopes to cot θ − cot 16θ. Shifting the index gives cot 2θ − cot 32θ.","difficulty":"very-hard","source":"JEE Advanced"},
  {"id":"math-trigonometry-141","question":"The range of f(x) = sin²x − 3 sin x + 2 over real x is:","options":["[−1/4, 6]","[0, 2]","[0, 6]","[−1/4, 2]"],"answer":2,"explanation":"With s = sin x ∈ [−1, 1], f = s² − 3s + 2 has its vertex at s = 3/2, outside the interval, so f is decreasing there: f(1) = 0 and f(−1) = 6. Using the vertex value −1/4 ignores that s cannot reach 3/2.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-trigonometry-142","question":"From the top of a tower, the angles of depression of two points on level ground, on opposite sides of the tower and in line with its foot, are 30° and 60°. If the points are 100 m apart, the height of the tower is:","options":["50√3 m","100/√3 m","25√3 m","25 m"],"answer":2,"explanation":"The points are at distances h cot 30° = h√3 and h cot 60° = h/√3 from the foot, on opposite sides, so h(√3 + 1/√3) = 4h/√3 = 100 and h = 25√3 m. Placing both points on the same side gives 2h/√3 = 100 and the trap 50√3 m.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-trigonometry-143","question":"A and B are acute angles with sin A = 3/5 and cos B = 5/13. Then sin(A + B) equals:","options":["33/65","56/65","16/65","63/65"],"answer":3,"explanation":"cos A = 4/5 and sin B = 12/13, so sin(A + B) = (3/5)(5/13) + (4/5)(12/13) = 15/65 + 48/65 = 63/65. Using the cos(A − B) pattern gives 56/65, and swapping the sign gives sin(B − A) = 33/65.","difficulty":"moderate","source":"JEE Main"},
  {"id":"math-trigonometry-144","question":"The value of tan 6° · tan 42° · tan 66° · tan 78° is:","options":["1","√3","1/2","1/√3"],"answer":0,"explanation":"By tan θ·tan(60° − θ)·tan(60° + θ) = tan 3θ: θ = 6° gives tan 6° tan 66° = tan 18°/tan 54°, and θ = 18° gives tan 42° tan 78° = tan 54°/tan 18°. Their product is 1.","difficulty":"very-hard","source":"JEE Advanced"},
  {"id":"math-trigonometry-145","question":"The value of sin(π/14) · sin(3π/14) · sin(5π/14) is:","options":["1/4","1/8","1/16","√7/8"],"answer":1,"explanation":"sin(π/14) = cos(3π/7), sin(3π/14) = cos(2π/7), sin(5π/14) = cos(π/7). The product cos(π/7)cos(2π/7)cos(4π/7) is −1/8, and cos(3π/7) = −cos(4π/7), so the value is 1/8.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-trigonometry-146","question":"If tan(π cos θ) = cot(π sin θ), then the value of cos(θ − π/4) can be:","options":["1/√2","1/(4√2)","1/(2√2)","√2/3"],"answer":2,"explanation":"π cos θ = π/2 − π sin θ + nπ, so sin θ + cos θ = 1/2 (n = 0; other n give |sum| > √2). Then cos(θ − π/4) = (cos θ + sin θ)/√2 = 1/(2√2).","difficulty":"hard","source":"JEE Main"},
  {"id":"math-trigonometry-147","question":"For the angles A, B, C of a triangle, the greatest value of sin A + sin B + sin C is:","options":["3/2","3√2/2","3","3√3/2"],"answer":3,"explanation":"sin is concave on [0, π], so by Jensen the sum is at most 3 sin(π/3) = 3√3/2, attained for the equilateral triangle.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-trigonometry-148","question":"The number of solutions of cos 4x + 10 = 11 cos 2x with x (in radians) in [0, 100] is:","options":["32","31","64","63"],"answer":0,"explanation":"With c = cos 2x: 2c² − 1 + 10 = 11c, so 2c² − 11c + 9 = 0, c = 1 (9/2 is impossible). Then x = nπ, and nπ ≤ 100 for n = 0, 1, …, 31: 32 solutions.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"math-trigonometry-149","question":"The angle of elevation of the top of a hill from the foot of a 50 m tower is 60°, and the angle of elevation of the top of the tower from the foot of the hill is 30°. The height of the hill is:","options":["100 m","150 m","50√3 m","75 m"],"answer":1,"explanation":"With d the distance between the feet: tan 30° = 50/d gives d = 50√3, and the hill height is d tan 60° = 50√3·√3 = 150 m.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-trigonometry-150","question":"In a triangle ABC the exradii satisfy r₁ = 2r₂ = 3r₃. Then a : b : c equals:","options":["3 : 4 : 5","1 : 2 : 3","5 : 4 : 3","6 : 3 : 2"],"answer":2,"explanation":"rᵢ = Δ/(s − side), so s − a : s − b : s − c = 1 : 2 : 3 = k : 2k : 3k. Then s = 6k and a, b, c = 5k, 4k, 3k.","difficulty":"very-hard","source":"JEE Advanced"},
  {"id":"math-trigonometry-151","question":"The sides of a triangle are x² + x + 1, 2x + 1 and x² − 1 (x > 1). Its greatest angle is:","options":["90°","135°","150°","120°"],"answer":3,"explanation":"With a = x² + x + 1, b = 2x + 1, c = x² − 1: b² + c² − a² = −(2x + 1)(x² − 1) = −bc, so cos A = −1/2 and A = 120°.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"math-trigonometry-152","question":"In any triangle ABC, (b + c) cos A + (c + a) cos B + (a + b) cos C equals:","options":["a + b + c","2(a + b + c)","abc","0"],"answer":0,"explanation":"Regroup as (b cos C + c cos B) + (c cos A + a cos C) + (a cos B + b cos A) = a + b + c by the projection formulas.","difficulty":"moderate","source":"JEE Main"},
  {"id":"math-trigonometry-153","question":"In triangle ABC, a = 2, b = 3 and sin A = 2/3. Then angle B is:","options":["60°","90°","30°","not determined: no such triangle"],"answer":1,"explanation":"By the sine rule sin B = b sin A/a = 3·(2/3)/2 = 1, so B = 90° (and A = sin⁻¹(2/3) < 90° is consistent).","difficulty":"moderate","source":"JEE Main"},
  {"id":"math-trigonometry-154","question":"For real x, the greatest value of sin x cos x + sin x + cos x is:","options":["3/2","1 + √2","1/2 + √2","2√2"],"answer":2,"explanation":"With t = sin x + cos x ∈ [−√2, √2], sin x cos x = (t² − 1)/2, so the expression is (t² − 1)/2 + t, increasing for t > −1. At t = √2 it equals 1/2 + √2.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"math-trigonometry-155","question":"For 0 < x < π/2, the least value of (sin x + cosec x)² + (cos x + sec x)² is:","options":["5","8","4","9"],"answer":3,"explanation":"The expression is 1 + 4 + cosec²x + sec²x = 5 + 4/sin²2x ≥ 5 + 4 = 9, with equality at x = π/4.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-trigonometry-156","question":"The number of integers k for which 7 cos x + 5 sin x = 2k + 1 has a real solution is:","options":["8","9","7","6"],"answer":0,"explanation":"The left side ranges over [−√74, √74] ≈ [−8.6, 8.6]. So −4.8 ≤ k ≤ 3.8, giving k = −4, −3, …, 3: eight integers.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-trigonometry-157","question":"If sin θ + sin²θ + sin³θ = 1, then cos⁶θ − 4cos⁴θ + 8cos²θ equals:","options":["1","4","2","8"],"answer":1,"explanation":"sin θ(1 + sin²θ) = 1 − sin²θ = cos²θ. Squaring: (1 − c)(2 − c)² = c² with c = cos²θ, which expands to c³ − 4c² + 8c = 4.","difficulty":"very-hard","source":"JEE Advanced"},
  {"id":"math-trigonometry-158","question":"If cos(x − y), cos x and cos(x + y) are in harmonic progression, then cos x · sec(y/2) equals:","options":["±1","±1/√2","±√2","±√3"],"answer":2,"explanation":"cos x = 2cos(x − y)cos(x + y)/(2 cos x cos y) gives cos²x cos y = cos²x − sin²y, so cos²x(1 − cos y) = sin²y and cos²x = 1 + cos y = 2cos²(y/2).","difficulty":"very-hard","source":"JEE Advanced"},
  {"id":"math-trigonometry-159","question":"If tan θ + tan(θ + π/3) + tan(θ + 2π/3) = 3, then tan 3θ equals:","options":["3","1/3","9","1"],"answer":3,"explanation":"The identity tan θ + tan(θ + π/3) + tan(θ + 2π/3) = 3 tan 3θ gives 3 tan 3θ = 3, so tan 3θ = 1.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-trigonometry-160","question":"The value of sin 20° + sin 40° + sin 60° + … + sin 180° (nine terms) is:","options":["cot 10°","tan 10°","cot 20°","0"],"answer":0,"explanation":"Σ sin kx (k = 1 to 9) = sin(9x/2) sin(5x)/sin(x/2) with x = 20°: sin 90° sin 100°/sin 10° = cos 10°/sin 10° = cot 10°.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-trigonometry-161","question":"If α + β = π/2 and β + γ = α, then tan α equals:","options":["tan β + tan γ","tan β + 2 tan γ","2(tan β + tan γ)","tan γ + 2 tan β"],"answer":1,"explanation":"tan γ = tan(α − β) = (tan α − tan β)/(1 + tan α tan β), and tan α tan β = 1. So 2 tan γ = tan α − tan β.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-trigonometry-162","question":"The angles of a triangle are in the ratio 4 : 1 : 1. The ratio of its greatest side to its perimeter is:","options":["2/(2 + √3)","1/(2 + √3)","√3/(2 + √3)","√3/2"],"answer":2,"explanation":"The angles are 120°, 30°, 30°, so the sides are in the ratio sin 120° : sin 30° : sin 30° = √3 : 1 : 1. The required ratio is √3/(2 + √3).","difficulty":"very-hard","source":"JEE Main"},
  {"id":"math-trigonometry-163","question":"In triangle ABC, a cos²(C/2) + c cos²(A/2) = 3b/2. Then the sides a, b, c are in:","options":["geometric progression","harmonic progression","no particular progression","arithmetic progression"],"answer":3,"explanation":"Using 2cos² = 1 + cos: (a + c) + (a cos C + c cos A) = 3b, and the bracket equals b. So a + c = 2b.","difficulty":"moderate","source":"JEE Main"},
  {"id":"math-trigonometry-164","question":"In a triangle ABC, (s − a)(s − b) = s(s − c), where s is the semi-perimeter. Then angle C is:","options":["90°","60°","120°","45°"],"answer":0,"explanation":"tan²(C/2) = (s − a)(s − b)/(s(s − c)) = 1, so C/2 = 45° and C = 90°.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-trigonometry-165","question":"The number of solutions of sin²x − sin x − 1 = 0 in [−2π, 2π] is:","options":["2","4","6","8"],"answer":1,"explanation":"sin x = (1 − √5)/2 ≈ −0.618 (the other root exceeds 1). This value is taken twice in each period of length 2π, so there are 4 solutions in an interval of length 4π.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-trigonometry-166","question":"The number of ordered pairs (α, β) with −π < α, β < π, cos(α − β) = 1 and cos(α + β) = 1/e is:","options":["2","1","4","0"],"answer":2,"explanation":"cos(α − β) = 1 forces α = β in this range. Then cos 2α = 1/e with 2α ∈ (−2π, 2π) has 4 solutions.","difficulty":"very-hard","source":"JEE Advanced"},
  {"id":"math-trigonometry-167","question":"For every real x, 3(sin x − cos x)⁴ + 6(sin x + cos x)² + 4(sin⁶x + cos⁶x) equals:","options":["11","12","14","13"],"answer":3,"explanation":"With p = sin x cos x: 3(1 − 2p)² + 6(1 + 2p) + 4(1 − 3p²) = 3 − 12p + 12p² + 6 + 12p + 4 − 12p² = 13.","difficulty":"moderate","source":"JEE Main"},
  {"id":"math-trigonometry-168","question":"The value of cos²10° − cos 10° cos 50° + cos²50° is:","options":["3/4","1/2","3/2","1"],"answer":0,"explanation":"Write cos²10° + cos²50° = 1 + ½(cos 20° + cos 100°) = 1 + cos 60° cos 40° and cos 10° cos 50° = ½(cos 60° + cos 40°). The difference is 1 − 1/4 = 3/4.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-trigonometry-169","question":"The sides a, b of triangle ABC are the roots of x² − 2√3x + 2 = 0 and C = 60°. Then c equals:","options":["2√3","√6","√10","2"],"answer":1,"explanation":"c² = a² + b² − ab = (a + b)² − 3ab = 12 − 6 = 6, so c = √6. Using + ab instead of − ab gives √10.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-trigonometry-170","question":"For an equilateral triangle, the circumradius R, inradius r and an exradius r₁ are in the ratio:","options":["1 : 2 : 3","3 : 1 : 2","2 : 1 : 3","2 : 1 : 4"],"answer":2,"explanation":"With side a: R = a/√3, r = a/(2√3), r₁ = Δ/(s − a) = (√3a²/4)/(a/2) = √3a/2. So R : r : r₁ = 2 : 1 : 3.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-trigonometry-171","question":"The greatest value of 2 sin x + 3 cos(x + π/6) over real x is:","options":["5","√13","√19","√7"],"answer":3,"explanation":"3 cos(x + π/6) = (3√3/2) cos x − (3/2) sin x, so the expression is (1/2) sin x + (3√3/2) cos x, whose amplitude is √(1/4 + 27/4) = √7.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-trigonometry-172","question":"The value of sin 47° + sin 61° − sin 11° − sin 25° is:","options":["cos 7°","sin 7°","cos 36°","sin 36°"],"answer":0,"explanation":"sin 47° − sin 25° = 2cos 36° sin 11° and sin 61° − sin 11° = 2cos 36° sin 25°. The sum is 2cos 36°(sin 11° + sin 25°) = 4cos 36° sin 18° cos 7° = cos 7°, since 4 sin 18° cos 36° = 1.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"math-trigonometry-173","question":"If cos A = 3/4, then 32 sin(A/2) sin(5A/2) equals:","options":["7","11","9","13"],"answer":1,"explanation":"2 sin(A/2) sin(5A/2) = cos 2A − cos 3A = 1/8 − (−9/16) = 11/16, so 32 sin(A/2) sin(5A/2) = 16·11/16 = 11.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-trigonometry-174","question":"In a triangle with a = 4, b = 6 and c = 8, the value of 8 cos A + 16 cos B + 4 cos C is:","options":["15","19","17","21"],"answer":2,"explanation":"cos A = 7/8, cos B = 11/16, cos C = −1/4, so the value is 7 + 11 − 1 = 17.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-trigonometry-175","question":"For the triangle with sides 5, 5 and 6, the sum of the circumradius and the inradius is:","options":["4","9/2","33/8","37/8"],"answer":3,"explanation":"Area = 12 and s = 8, so r = 12/8 = 3/2 and R = abc/(4Δ) = 150/48 = 25/8. R + r = 37/8.","difficulty":"moderate","source":"JEE Main"},
  {"id":"math-trigonometry-176","question":"If x = sec θ − tan θ and y = cosec θ + cot θ, then xy + 1 equals:","options":["x + y","y − x","2xy","1 − xy"],"answer":1,"explanation":"With s = sin θ, c = cos θ: xy + 1 = [(1 − s)(1 + c) + sc]/(sc) = (1 + c − s)/(sc), and y − x = [c(1 + c) − s(1 − s)]/(sc) = (1 + c − s)/(sc). So xy + 1 = y − x.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"math-trigonometry-177","question":"The range of sin²x + 2 cos x over real x is:","options":["[0, 2]","[−1, 2]","[−2, 1]","[−2, 2]"],"answer":3,"explanation":"With c = cos x ∈ [−1, 1], the expression is 1 − c² + 2c = 2 − (c − 1)², which runs from −2 (c = −1) to 2 (c = 1).","difficulty":"hard","source":"JEE Main"},
  {"id":"math-trigonometry-178","question":"The least value of cos²θ − 6 sin θ cos θ + 3 sin²θ + 2 over real θ is:","options":["4 − √10","2","4 − √5","0"],"answer":0,"explanation":"The expression is 4 − cos 2θ − 3 sin 2θ, and cos 2θ + 3 sin 2θ ≤ √10, so the least value is 4 − √10.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"math-trigonometry-179","question":"In triangle ABC, tan(A/2) = 5/6 and tan(C/2) = 2/5. Then the sides a, b, c are in:","options":["geometric progression","arithmetic progression","harmonic progression","no particular progression"],"answer":1,"explanation":"tan(A/2) tan(C/2) = (s − b)/s = 1/3, so b = 2s/3 and a + c = 2s − b = 2b.","difficulty":"very-hard","source":"JEE Main"},
];

export default questions;
